Q: pure javascript to check if something has hover (without setting on mouseover/out) A: <p>You can use <a href="https://developer.mozilla.org/en-US/docs/DOM/Document.querySelector" rel="nofollow noreferrer">querySelector</a> <strong>for IE&gt;=8</strong></p>

<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function isHover(e) {
  return (e.parentElement.querySelector(':hover') === e);
}


const myDiv = document.getElementById('mydiv');;
document.addEventListener('mousemove', function checkHover() {
  const hovered = isHover(myDiv);
  if (hovered !== checkHover.hovered) {
    console.log(hovered ? 'hovered' : 'not hovered');
    checkHover.hovered = hovered;
  }
});</code></pre>
